namespace ghidra.app.plugin.core.compositeeditor;



using docking;
using generic.theme;
using ghidra.app.services;
using ghidra.program.model.data;

/**
 * Shows the editor's data type in the UI using the {@link DataTypeManagerService}.
 */
public class ShowDataTypeInTreeAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Show In Data Type Manager";

	// This action should go after the row-based actions, which have this group:
	// 3_COMPONENT_EDITOR_ACTION
	private static readonly string TOOLBAR_GROUP = "4_COMPONENT_EDITOR_ACTION";
	private static readonly Icon ICON = new GIcon("icon.plugin.composite.editor.show.type");

	public ShowDataTypeInTreeAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, TOOLBAR_GROUP, null /*popupPath*/, null /*menuPath*/, ICON)
    {
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		DataTypeManagerService dtmService = tool.getService(typeof(DataTypeManagerService));
		DataTypeManager dtm = provider.getDataTypeManager();
		DataTypePath path = provider.getDtPath();
		DataType dt = dtm.getDataType(path);
		dtmService.setDataTypeSelected(dt);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (hasIncompleteFieldEntry()) {
			return false;
		}
		DataTypeManager dtm = provider.getDataTypeManager();
		DataTypePath path = provider.getDtPath();
		DataType dt = dtm.getDataType(path);
		return dt != null;
	}
}
